.initializers.normal(stddev=1 / np.sqrt(width)),\\n            (1, np.prod(seqshape), width),\\n            dtype,\\n        )\\n    if typ == \\\"sincos2d\\\":\\n        return posemb_sincos_2d(*seqshape, width, dtype=dtype)\\n    raise ValueError(f\\\"Unknown posemb type: {typ}\\\")\\n\\n\\nclass MlpBlock(nn.Module):\\n    \\\"\\\"\\\"Transformer MLP / feed-forward block.\\\"\\\"\\\"\\n\\n    mlp_dim: int | None = None  # Defaults to 4x input dim\\n    dropout: float = 0.0\\n    dtype_mm: str = \\\"float32\\\"\\n\\n    @nn.compact\\n    def __call__(self, x, deterministic=True):  # noqa: FBT002\\n        \\\"\\\"\\\"Applies Transformer MlpBlock module.\\\"\\\"\\\"\\n        inits = {\\n            \\\"kernel_init\\\": nn.initializers.xavier_uniform(),\\n            \\\"bias_init\\\": nn.initializers.normal(stddev=1e-6),\\n        }\\n\\n        _, _, d = x.shape  # n,l,d\\n        x = nn.Dense(self.mlp_dim or 4 * d, dtype=self.dtype_mm, **inits)(x)\\n        x = nn.gelu(x)\\n        x = nn.Dropout(rate=self.dropout)(x, deterministic)\\n        return nn.Dense(d, dtype=self.dtype_mm, **inits)(x)\\n\\n\\nclass Encoder1DBlock(nn.Module):\\n    \\\"\\\"\\\"Single transformer encoder block (MHSA + MLP).\\\"\\\"\\\"\\n\\n    mlp_dim: int | None = None  # Defaults to 4x input dim\\n    num_heads: int = 12\\n    dropout: float = 0.0\\n    dtype_mm: str = \\\"float32\\\"\\n\\n    @nn.compact\\n    def __call__(self, x, deterministic=True):  # noqa: FBT002\\n        out = {}\\n        x = sharding.activation_sharding_constraint(x)\\n        y = nn.LayerNorm(dtype=self.dtype_mm)(x)\\n        y = out[\\\"sa\\\"] = nn.MultiHeadDotProductAttention(\\n            num_heads=self.num_heads,\\n            kernel_init=nn.initializers.xavier_uniform(),\\n            deterministic=deterministic,\\n            dtype=self.dtype_mm,\\n        )(y, y)\\n        y = sharding.activation_sharding_constraint(y)\\n        y = nn.Dropout(rate=self.dropout)(y, deterministic)\\n        x = out[\\\"+sa\\\"] = x + y\\n\\n        y = nn.LayerNorm(dtype=self.dtype_mm)(x)\\n        y = out[\\\"mlp\\\"] = MlpBlock(\\n            mlp_dim=self.mlp_dim,\\n            dropout=self.dropout,\\n            dtype_mm=self.dtype_mm,\\n        )(y, deterministic)\\n        y = sharding.activation_sharding_constraint(y)\\n        y = nn.Dropout(rate=self.dropout)(y, deterministic)\\n        x = out[\\\"+mlp\\\"] = x + y\\n        x = sharding.activation_sharding_constraint(x)\\n        return x, out\\n\\n\\nclass Encoder(nn.Module):\\n    \\\"\\\"\\\"Transformer Model Encoder for sequence to sequence translation.\\\"\\\"\\\"\\n\\n    depth: int\\n    mlp_dim: int | None = None  # Defaults to 4x input dim\\n    num_heads: int = 12\\n    dropout: float = 0.0\\n   \\n\\n... [截断: 输出过长，省略 4078 字符] ...\\n\\nst back to dtype_mm (potentially half precision)\\n        x = x.astype(self.dtype_mm)\\n\\n        x, out[\\\"encoder\\\"] = Encoder(\\n            depth=self.depth,\\n            mlp_dim=self.mlp_dim,\\n            num_heads=self.num_heads,\\n            dropout=self.dropout,\\n            scan=self.scan,\\n            remat_policy=self.remat_policy,\\n            dtype_mm=self.dtype_mm,\\n            name=\\\"Transformer\\\",\\n        )(x, deterministic=not train)\\n        encoded = out[\\\"encoded\\\"] = x\\n\\n        if self.pool_type == \\\"map\\\":\\n            x = out[\\\"head_input\\\"] = MAPHead(\\n                num_heads=self.num_heads,\\n                mlp_dim=self.mlp_dim,\\n                dtype=self.dtype_mm,\\n            )(x)\\n        elif self.pool_type == \\\"gap\\\":\\n            x = out[\\\"head_input\\\"] = jnp.mean(x, axis=1)\\n        elif self.pool_type == \\\"0\\\":\\n            x = out[\\\"head_input\\\"] = x[:, 0]\\n        elif self.pool_type == \\\"tok\\\":\\n            x = out[\\\"head_input\\\"] = x[:, 0]\\n            encoded = encoded[:, 1:]\\n        elif self.pool_type == \\\"none\\\":\\n            pass\\n        else:\\n            raise ValueError(f\\\"Unknown pool type: '{self.pool_type}'\\\")\\n\\n        x_2d = jnp.reshape(encoded, [n, h, w, -1])\\n\\n        if self.rep_size:\\n            rep_size = self.width if self.rep_size is True else self.rep_size\\n            hid = nn.Dense(rep_size, dtype=self.dtype_mm, name=\\\"pre_logits\\\")\\n            # NOTE: In the past we did not include tanh in pre_logits.\\n            # For few-shot, it should not matter much, as it whitens anyways.\\n            x_2d = nn.tanh(hid(x_2d))\\n            x = nn.tanh(hid(x))\\n\\n        out[\\\"pre_logits_2d\\\"] = x_2d\\n        out[\\\"pre_logits\\\"] = x\\n\\n        if self.num_classes:\\n            kw = {\\\"kernel_init\\\": nn.initializers.zeros} if self.head_zeroinit else {}\\n            head = nn.Dense(self.num_classes, dtype=self.dtype_mm, name=\\\"head\\\", **kw)\\n            x_2d = out[\\\"logits_2d\\\"] = head(x_2d)\\n            x = out[\\\"logits\\\"] = head(x)\\n\\n        return x, out\\n\\n\\ndef Module(num_classes=None, *, variant=None, **kw):  # pylint: disable=invalid-name  # noqa: N802\\n    \\\"\\\"\\\"Factory function, because linen really don't like what I'm doing!\\\"\\\"\\\"\\n    return _Module(num_classes, **{**decode_variant(variant), **kw})\\n\\n\\ndef decode_variant(variant):\\n    \\\"\\\"\\\"Converts a string like \\\"B\\\" or \\\"B/32\\\" into a params dict.\\\"\\\"\\\"\\n    if variant is None:\\n        return {}\\n\\n    v, patch = variant, {}\\n    if \\\"/\\\" in variant:\\n        v, patch = variant.split(\\\"/\\\")\\n        patch = {\\\"patch_size\\\": (int(patch), int(patch))}\\n\\n    return {\\n        # pylint:disable=line-too-long\\n        # Reference: Table 2 of https://arxiv.org/abs/2106.04560.\\n        \\\"width\\\": {\\n            \\\"mu\\\": 32,\\n            \\\"Ti\\\": 192,\\n            \\\"S\\\": 384,\\n            \\\"M\\\": 512,\\n            \\\"B\\\": 768,\\n            \\\"L\\\": 1024,\\n            \\\"So400m\\\": 1152,\\n          