te).unsqueeze(0).to(device),\n        \"task\": [task_description],\n    }\n    return batch\n\ndef get_libero_env(task, resolution, seed):\n    task_description = task.language\n    task_bddl = Path(get_libero_path(\"bddl_files\")) / task.problem_folder / task.bddl_file\n    env_args = {\"bddl_file_name\": task_bddl, \"camera_heights\": resolution, \"camera_widths\": resolution}\n    env = OffScreenRenderEnv(**env_args)\n    env.seed(seed)\n    return env, task_description\n\n# ─── Main eval loop ───\ntotal_success = 0\ntotal_episodes = 0\nresults = {\"config\": {\n    \"model\": \"pi05\",\n    \"ckpt\": CKPT_DIR,\n    \"suite\": TASK_SUITE,\n    \"prune_ratio\": PRUNE_RATIO,\n    \"n_episodes_per_task\": N_EPISODES_PER_TASK,\n    \"seed\": SEED,\n    \"vision_tokens_per_image\": n_patches_per_img,\n    \"n_images\": n_images,\n    \"total_vision_tokens\": n_patches_per_img * n_images,\n}, \"per_task\": {}, \"overall_sr\": 0.0}\n\nfor task_id in range(n_tasks):\n    task = task_suite.get_task(task_id)\n    initial_states = task_suite.get_task_init_states(task_id)\n    env, task_description = get_libero_env(task, 256, SEED)\n\n    task_successes = 0\n    task_episodes = 0\n\n    for ep in range(N_EPISODES_PER_TASK):\n        env.reset()\n        obs = env.set_init_state(initial_states[ep])\n\n        # Wait for objects to stabilize\n        for _ in range(10):\n            obs, _, _, _ = env.step([0.0]*6 + [-1.0])\n\n        policy.reset()\n        action_queue = deque()\n        done = False\n\n        for t in range(max_steps):\n            if not action_queue:\n                batch = prepare_batch(obs, task_description, DEVICE)\n                with torch.no_grad():\n                    actions = policy.predict_action_chunk(batch)  # (1, chunk, action_dim)\n                action_chunk = actions[0].cpu().numpy()  # (chunk, action_dim)\n                for a in action_chunk[:REPLAN_STEPS]:\n                    action_queue.append(a[:7])  # only first 7 dims\n\n            action = action_queue.popleft()\n            obs, reward, done, info = env.step(action.tolist())\n            if done:\n                task_successes += 1\n                total_success += 1\n                break\n\n        task_episodes += 1\n        total_episodes += 1\n\n        if (ep + 1) % 10 == 0 or ep == 0:\n            log.info(f\"  Task {task_id} [{task_description}] ep {ep+1}/{N_EPISODES_PER_TASK}: \"\n                     f\"{task_successes}/{task_episodes} = {task_successes/task_episodes*100:.1f}%\")\n\n    task_sr = task_successes / task_episodes\n    results[\"per_task\"][task_description] = {\n        \"task_id\": task_id,\n        \"successes\": task_successes,\n        \"episodes\": task_episodes,\n        \"sr\": task_sr,\n    }\n    log.info(f\"Task {task_id} done: SR={task_sr*100:.1f}% ({task_successes}/{task_episodes})\")\n    log.info(f\"  Running total: {total_success}/{total_episodes} = {total_success/total_episodes*100:.1f}%\")\n\n    env.close()\n\nresults[\"overall_sr\"] = total_success / total_episodes\nresults[\"total_successes\"] = total_success\nresults[\"total_episodes\"] = total_episodes\n\n# Save results\nRESULTS_DIR.mkdir(parents=True, exist_ok=True)\nif PRUNE_RATIO > 0:\n    fname = f\"pi05_random_prune_k{1-PRUNE_RATIO:.2f}_{TASK_SUITE}.json\"\nelse:\n    fname = f\"pi05_baseline_{TASK_SUITE}.json\"\nout_path = RESULTS_DIR / fname\nwith open(out_path, \"w\") as f:\n    json.dump(results, f, indent=2)\n\nlog.info(f\"\\n{'='*60}\")\nlog.info(f\"FINAL RESULTS: {TASK_SUITE}\")\nlog.info(f\"  Prune ratio: {PRUNE_RATIO}\")\nlog.info(f\"  Overall SR: {results['overall_sr']*100:.1f}% ({total_success}/{total_episodes})\")\nlog.info(f\"  Saved to: {out_path}\")\nlog.info(f\"{'='*60}\")\nPYEOF\necho \"Script written\"","account":"root"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":422,"cache_read_input_tokens":143837,"cache_creati