{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_01V41qSLJdaVoZH1gepTygZX","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01D9EM7jFrH7THVtxFoM1W8z","name":"mcp__agent-ml-research__ssh_execute","input":{"server":"cqa1-33015","command":"cat > /root/autodl-tmp/importance_margin_vla_compress/test_pi05_quick.py << 'PYEOF'\n\"\"\"Quick smoke test: load model + run 1 episode to verify pipeline works.\"\"\"\nimport os, sys, math, logging, types\nfrom pathlib import Path\nfrom collections import deque\n\nos.environ[\"CUDA_VISIBLE_DEVICES\"] = \"0\"\nos.environ[\"MUJOCO_GL\"] = \"egl\"\nos.environ[\"HF_HOME\"] = \"/root/autodl-tmp/.hf_cache\"\nos.environ[\"TRANSFORMERS_OFFLINE\"] = \"1\"\nos.environ[\"HF_HUB_OFFLINE\"] = \"1\"\n\nimport numpy as np\nimport torch\n\nlogging.basicConfig(level=logging.INFO, force=True, format=\"%(asctime)s %(message)s\")\nlog = logging.getLogger(__name__)\n\n# ─── Load model ───\nCKPT_DIR = \"/root/autodl-tmp/pi05-libero-finetuned\"\nDEVICE = \"cuda:0\"\n\nlog.info(\"Loading Pi0.5...\")\nfrom lerobot.policies.pi05.modeling_pi05 import PI05Policy\npolicy = PI05Policy.from_pretrained(CKPT_DIR)\npolicy = policy.to(DEVICE)\npolicy.eval()\nlog.info(f\"Model loaded: {sum(p.numel() for p in policy.parameters())/1e6:.1f}M params\")\nlog.info(f\"Config: n_action_steps={policy.config.n_action_steps}, chunk_size={policy.config.chunk_size}\")\nlog.info(f\"Image features: {list(policy.config.image_features.keys())}\")\n\npreprocessor = policy.preprocessor\npostprocessor = policy.postprocessor\n\n# ─── LIBERO setup ───\nfrom libero.libero import benchmark, get_libero_path\nfrom libero.libero.envs import OffScreenRenderEnv\n\nnp.random.seed(7)\nsuite = benchmark.get_benchmark_dict()[\"libero_object\"]()\ntask = suite.get_task(0)\ninit_states = suite.get_task_init_states(0)\ndesc = task.language\nbddl = Path(get_libero_path(\"bddl_files\")) / task.problem_folder / task.bddl_file\nenv = OffScreenRenderEnv(bddl_file_name=bddl, camera_heights=256, camera_widths=256)\nenv.seed(7)\n\ndef quat_to_axisangle(quat):\n    q = quat.copy()\n    q[3] = max(-1.0, min(1.0, q[3]))\n    den = np.sqrt(1.0 - q[3]**2)\n    if abs(den) < 1e-8:\n        return np.zeros(3, dtype=np.float32)\n    return (q[:3] * 2.0 * math.acos(q[3]) / den).astype(np.float32)\n\nlog.info(f\"Task: {desc}\")\nlog.info(\"Running 1 episode...\")\n\nenv.reset()\nobs = env.set_init_state(init_states[0])\nfor _ in range(10):\n    obs, _, _, _ = env.step([0.0]*6 + [-1.0])\n\npolicy.reset()\naction_queue = deque()\ndone = False\n\nfor t in range(280):\n    if not action_queue:\n        base_img = obs[\"agentview_image\"]\n        wrist_img = obs[\"robot0_eye_in_hand_image\"]\n        base_t = torch.from_numpy(base_img.copy()).permute(2, 0, 1).float() / 255.0\n        wrist_t = torch.from_numpy(wrist_img.copy()).permute(2, 0, 1).float() / 255.0\n        eef_pos = obs[\"robot0_eef_pos\"]\n        eef_quat = obs[\"robot0_eef_quat\"]\n        gripper_qpos = obs[\"robot0_gripper_qpos\"]\n        state = np.concatenate([eef_pos, quat_to_axisangle(eef_quat), gripper_qpos]).astype(np.float32)\n\n        raw = {\n            \"observation.images.image\": base_t,\n            \"observation.images.image2\": wrist_t,\n            \"observation.state\": torch.from_numpy(state),\n            \"task\": desc,\n        }\n        batch = preprocessor(raw)\n        log.info(f\"  Step {t}: batch keys = {list(batch.keys())}\")\n        \n        with torch.no_grad():\n            actions = policy.predict_action_chunk(batch)\n        log.info(f\"  Actions shape: {actions.shape}\")\n        \n        post_out = postprocessor({\"action\": actions[0]})\n        action_np = post_out[\"action\"].numpy()\n        log.info(f\"  Post-processed actions shape: {action_np.shape}\")\n        \n        for a in action_np[:5]:\n            action_queue.append(a[:7])\n\n    action = action_queue.popleft()\n    obs, reward, done, info = env.step(action.tolist())\n    if done:\n        log.info(f\"  SUCCESS at step {t}!\")\n        break\n    if t % 50 == 0:\n        log.info(f\"  Step {t}, done={done}\")\n\nif not done:\n    log.info(f\"  FAILURE (timeout)\")\n\nenv.close()\nlog.info(\"Smoke test complete!\")\nPYEOF\necho \"Test script created\"","account":"root"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":3736,"cache_read_input_tokens":158302,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":3736},"output_tokens":1,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"41deb33a-262b-4c9e-b356-aa52f2c133b4","uuid":"045ed84a-403b-4cb1-9462-1cea9a80630c"}
